import os
import re
from typing import Any, Dict, List, Tuple, Union

import requests

PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _normalize_input(text: Union[str, Dict[str, Any]]) -> str:
    if isinstance(text, str):
        return text
    if isinstance(text, dict):
        for key in ("text", "content", "message", "body"):
            val = text.get(key)
            if isinstance(val, str):
                return val
    raise TypeError("text must be a string or a dict containing a text-like field")


def _request_perspective_score(text: str) -> Dict[str, Any]:
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise EnvironmentError("PERSPECTIVE_API_KEY is required")

    requested_attributes = {
        "TOXICITY": {},
        "INSULT": {},
        "PROFANITY": {},
        "THREAT": {},
        "SEXUALLY_EXPLICIT": {},
        "IDENTITY_ATTACK": {},
    }

    payload = {
        "comment": {"text": text},
        "requestedAttributes": requested_attributes,
        "spanAnnotations": True,
        "doNotStore": True,
    }

    resp = requests.post(
        PERSPECTIVE_API_URL,
        params={"key": api_key},
        json=payload,
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()


def _extract_unsafe_spans(text: str, response: Dict[str, Any], threshold: float) -> List[Dict[str, Any]]:
    spans: List[Dict[str, Any]] = []
    attr_scores = response.get("attributeScores", {})

    for attr_name, attr_payload in attr_scores.items():
        summary_score = (
            attr_payload.get("summaryScore", {})
            .get("value", 0.0)
        )
        if summary_score < threshold:
            continue

        span_scores = attr_payload.get("spanScores", []) or []
        for span in span_scores:
            score = span.get("score", {}).get("value", 0.0)
            if score < threshold:
                continue
            begin = int(span.get("begin", 0))
            end = int(span.get("end", 0))
            if begin < 0 or end <= begin or begin >= len(text):
                continue
            end = min(end, len(text))
            spans.append(
                {
                    "start": begin,
                    "end": end,
                    "text": text[begin:end],
                    "attribute": attr_name,
                    "score": score,
                }
            )

    spans.sort(key=lambda x: (x["start"], -(x["end"] - x["start"]), -x["score"]))

    merged: List[Dict[str, Any]] = []
    for span in spans:
        if not merged:
            merged.append(span)
            continue
        last = merged[-1]
        if span["start"] <= last["end"]:
            if span["end"] > last["end"] or span["score"] > last["score"]:
                last["end"] = max(last["end"], span["end"])
                last["text"] = text[last["start"] : last["end"]]
                last["attribute"] = last["attribute"] if last["score"] >= span["score"] else span["attribute"]
                last["score"] = max(last["score"], span["score"])
        else:
            merged.append(span)

    return merged


def _redact_text(text: str, spans: List[Dict[str, Any]], redaction: str = "[REDACTED]") -> str:
    if not spans:
        return text

    out = []
    cursor = 0
    for span in sorted(spans, key=lambda s: s["start"]):
        start = max(0, min(len(text), span["start"]))
        end = max(start, min(len(text), span["end"]))
        if start < cursor:
            continue
        out.append(text[cursor:start])
        out.append(redaction)
        cursor = end
    out.append(text[cursor:])
    return "".join(out)


def flag_or_redact_unsafe_spans(
    text: Union[str, Dict[str, Any]],
    mode: str = "redact",
    threshold: float = 0.5,
    redaction: str = "[REDACTED]",
) -> Dict[str, Any]:
    """
    Uses Perspective API to detect unsafe spans in text.

    Returns:
        {
          "text": original_text,
          "unsafe_spans": [...],
          "redacted_text": ...,
          "is_unsafe": bool
        }
    """
    original_text = _normalize_input(text)
    response = _request_perspective_score(original_text)
    unsafe_spans = _extract_unsafe_spans(original_text, response, threshold=threshold)

    result: Dict[str, Any] = {
        "text": original_text,
        "unsafe_spans": unsafe_spans,
        "is_unsafe": bool(unsafe_spans),
    }

    if mode not in {"flag", "redact"}:
        raise ValueError("mode must be either 'flag' or 'redact'")

    if mode == "redact":
        result["redacted_text"] = _redact_text(original_text, unsafe_spans, redaction=redaction)

    return result
